code = '''from collections import Counter, deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] != 0 and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            y0, y1 = min(y for y, x in cells), max(y for y, x in cells) + 1
            x0, x1 = min(x for y, x in cells), max(x for y, x in cells) + 1
            comps.append((y0, x0, y1-y0, x1-x0))

    if not comps:
        return g
    dims = Counter((ch, cw) for _, _, ch, cw in comps)
    th, tw = max(dims, key=lambda z: (dims[z], z[0]*z[1]))
    full = [(y, x) for y, x, ch, cw in comps if (ch, cw) == (th, tw)]
    if not full:
        return g
    ys, xs = sorted(set(y for y, x in full)), sorted(set(x for y, x in full))
    py = min((b-a for a, b in zip(ys, ys[1:]) if b > a), default=th)
    px = min((b-a for a, b in zip(xs, xs[1:]) if b > a), default=tw)
    ybase, xbase = min(ys), min(xs)

    # Each tile has a uniform outer color and a smaller, repeated colored mark.
    marks = {}
    for y0, x0 in full:
        tile = [g[y][x0:x0+tw] for y in range(y0, y0+th)]
        frame = Counter(v for row in tile for v in row).most_common(1)[0][0]
        colors = Counter(v for row in tile for v in row if v != frame)
        if not colors:
            continue
        color = colors.most_common(1)[0][0]
        mask = frozenset((dy, dx) for dy in range(th) for dx in range(tw) if tile[dy][dx] == color)
        if not mask:
            continue
        marks[((y0-ybase)//py, (x0-xbase)//px)] = (color, mask)

    by_color = {}
    for (tr, tc), (color, mask) in marks.items():
        by_color.setdefault(color, []).append((tr, tc, mask))

    for color, items in by_color.items():
        if len(items) != 4:
            continue
        rows = sorted({r for r, c, m in items})
        cols = sorted({c for r, c, m in items})
        if len(rows) != 2 or len(cols) != 2 or {(r,c) for r,c,m in items} != {(r,c) for r in rows for c in cols}:
            continue
        mask = items[0][2]
        top, bottom = rows
        left, right = cols
        # Bridge the two horizontal sides and two vertical sides, changing only gaps.
        for tr in rows:
            y0 = ybase + tr*py
            for dy, dx in mask:
                y, x0 = y0+dy, xbase + left*px + dx
                end = xbase + right*px + dx
                for x in range(x0+tw, end):
                    if g[y][x] == 0:
                        g[y][x] = color
        for tc in cols:
            x0 = xbase + tc*px
            for dy, dx in mask:
                x, y0 = x0+dx, ybase + top*py + dy
                end = ybase + bottom*py + dy
                for y in range(y0+th, end):
                    if g[y][x] == 0:
                        g[y][x] = color
    return g
