def make_grid(H,W,th,tw,py,px,frame,tiles,base=1):
    g=[[0]*W for _ in range(H)]
    for tr,row in enumerate(tiles):
        for tc,val in enumerate(row):
            y0,x0=base+tr*py,base+tc*px
            if val is None: continue
            for dy in range(th):
                for dx in range(tw):
                    if y0+dy<H and x0+dx<W:
                        g[y0+dy][x0+dx]=frame
            # all non-frame pixels of the inner mark
            for dy in range(1,th-1):
                for dx in range(1,tw-1):
                    if y0+dy<H and x0+dx<W:
                        g[y0+dy][x0+dx]=val
    return g

def oracle(g,th,tw,py,px,rects,base=1):
    out=[r[:] for r in g]
    for color,(r1,r2,c1,c2) in rects:
        # mark shape inferred from a corner tile
        y=base+r1*py; x=base+c1*px
        mask=[(dy,dx) for dy in range(1,th-1) for dx in range(1,tw-1) if g[y+dy][x+dx]==color]
        for tr in (r1,r2):
            for dy,dx in mask:
                yy=base+tr*py+dy
                for xx in range(base+c1*px+dx+tw,base+c2*px+dx):
                    if out[yy][xx]==0: out[yy][xx]=color
        for tc in (c1,c2):
            for dy,dx in mask:
                xx=base+tc*px+dx
                for yy in range(base+r1*py+dy+th,base+r2*py+dy):
                    if out[yy][xx]==0: out[yy][xx]=color
    return out

